"var w = $("#" + id);

var die1 = w.find("#die1");
var die2 = w.find("#die2");
var sumVal = w.find(".sum-value");
var pointVal = w.find(".point-value");
var status = w.find(".status");
var btn = w.find(".roll-btn");

var point = null;
var rolling = false;

function rollDie() {
  return Math.floor(Math.random() * 6) + 1;
}

function updateDice(d1, d2) {
  die1.text(d1);
  die2.text(d2);
  sumVal.text(d1 + d2);
}

function setStatus(msg, cls) {
  status.text(msg).removeClass("win lose");
  if (cls) status.addClass(cls);
}

btn.on("click", function() {
  if (rolling) return;
  rolling = true;
  btn.prop("disabled", true);
  die1.addClass("rolling");
  die2.addClass("rolling");
  setStatus("Rolling...");

  var steps = 0;
  var interval = setInterval(function() {
    updateDice(rollDie(), rollDie());
    steps++;
    if (steps >= 10) {
      clearInterval(interval);
      finishRoll();
    }
  }, 80);
});

function finishRoll() {
  var d1 = rollDie();
  var d2 = rollDie();
  var total = d1 + d2;
  updateDice(d1, d2);
  die1.removeClass("rolling");
  die2.removeClass("rolling");

  if (point === null) {
    // Come-out roll
    if (total === 7 || total === 11) {
      setStatus(total + " — Natural! You win!", "win");
      btn.text("Play Again");
      rolling = false;
      btn.prop("disabled", false);
    } else if (total === 2 || total === 3 || total === 12) {
      setStatus(total + " — Craps! You lose.", "lose");
      btn.text("Play Again");
      rolling = false;
      btn.prop("disabled", false);
    } else {
      point = total;
      pointVal.text(point);
      setStatus("Point is " + point + ". Roll again!");
      btn.text("Roll");
      rolling = false;
      btn.prop("disabled", false);
    }
  } else {
    // Point phase
    if (total === point) {
      setStatus(total + " — You hit the point! You win!", "win");
      point = null;
      pointVal.text("None");
      btn.text("Play Again");
      rolling = false;
      btn.prop("disabled", false);
    } else if (total === 7) {
      setStatus("7 — Seven out! You lose.", "lose");
      point = null;
      pointVal.text("None");
      btn.text("Play Again");
      rolling = false;
      btn.prop("disabled", false);
    } else {
      setStatus(total + " — Keep rolling...");
      rolling = false;
      btn.prop("disabled", false);
    }
  }
}
